(()=>{if(document.getElementById("onmom-dataset-control"))return;const box=document.createElement("section");box.id="onmom-dataset-control";box.innerHTML='<div class="odc-head"><div><strong>\uc0c1\ub2f4 \ub370\uc774\ud130\uc14b</strong><small>\uc2e4\ub370\uc774\ud130 / 21\uc77c \ud569\uc131 \uc2dc\ub098\ub9ac\uc624</small></div><button type="button" aria-label="\uc811\uae30">\u2212</button></div><div class="odc-body"><label>\ud65c\uc131 \ub370\uc774\ud130\uc14b<select aria-label="\uc0c1\ub2f4 \ub370\uc774\ud130\uc14b \uc120\ud0dd"></select></label><p class="odc-status" role="status">\ubd88\ub7ec\uc624\ub294 \uc911...</p><p class="odc-note"></p></div>';document.body.append(box);const body=box.querySelector(".odc-body"),toggle=box.querySelector("button"),select=box.querySelector("select"),status=box.querySelector(".odc-status"),note=box.querySelector(".odc-note");const request=async(path,options)=>{const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw new Error(data.error||data.detail||"request failed");return data};const load=async()=>{status.textContent="\ubd88\ub7ec\uc624\ub294 \uc911...";select.disabled=true;try{const data=await request("/api/counseling/datasets"),active=data.active_dataset||{},datasets=Array.isArray(data.datasets)?data.datasets:[];select.replaceChildren();for(const item of datasets){const option=document.createElement("option");option.value=item.id;option.textContent=item.label||item.id;option.selected=item.id===active.id;select.append(option)}status.textContent=(active.label||active.id||"\uc5c6\uc74c")+" \ud65c\uc131";note.textContent=active.id==="default"?"\uc2e4\ub370\uc774\ud130 \ubaa8\ub2c8\ud130\ub9c1 \uc911":"\ud569\uc131 \uc2dc\ub098\ub9ac\uc624 \uc120\ud0dd\ub428 \u00b7 \uc790\ub3d9 \ub2a5\ub3d9 \ubc1c\ud654 \ucc28\ub2e8";note.dataset.scenario=active.id==="default"?"false":"true";select.disabled=false}catch(error){status.textContent="\ub370\uc774\ud130\uc14b\uc744 \ubd88\ub7ec\uc624\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.";note.textContent=error.message}};select.addEventListener("change",async()=>{select.disabled=true;status.textContent="\ubcc0\uacbd \uc911...";try{await request("/api/counseling/datasets/select",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({dataset_id:select.value})});await load()}catch(error){status.textContent="\ubcc0\uacbd\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.";note.textContent=error.message;select.disabled=false}});toggle.addEventListener("click",()=>{const collapsed=body.hidden=!body.hidden;toggle.textContent=collapsed?"+":"\u2212";toggle.setAttribute("aria-label",collapsed?"\ud3bc\uce58\uae30":"\uc811\uae30")});load()})();
